      suspect_links: { title: 'Requirements with suspect links: {n}', detail: 'The requirement or a linked test changed after the link was made or last confirmed, so the tests may no longer verify the requirement.', fix: 'Check each link and confirm it, or update the test.' },
      obligation_missing: { title: 'Requirements without an obligation level: {n}', detail: 'A requirement without an obligation level does not say whether it must, should or may be fulfilled.', fix: 'Set the obligation (MUST, SHOULD, MAY …) in the requirement, and write the keyword in the text.' },
      keyword_missing: { title: 'Obligation level in the field but no keyword in the text: {n}', detail: 'The level is only in the field; readers of the text (or an export) do not see it.', fix: 'Write the keyword in capitals in the description, e.g. "The system MUST …".' },
      obligation_mismatch: { title: 'Text and obligation field disagree: {n}', detail: 'The text uses a keyword of another level than the obligation field (shown as field ≠ text).', fix: 'Make the field and the text agree.' },
      multiple_levels: { title: 'Requirements that mix obligation levels: {n}', detail: 'A requirement with both MUST and MAY is really several requirements.', fix: 'Split it so each requirement has one obligation level.' },
      spread_all_mandatory: { title: '{percent} % of the requirements are mandatory', detail: 'When almost everything is MUST/SHALL, nothing can be prioritised and the commitment becomes hard to keep.', fix: 'Check whether some requirements are really recommendations (SHOULD) or options (MAY).' },
      spread_many_optional: { title: '{percent} % of the requirements are optional (MAY)', detail: 'Many optional requirements say little about what must be delivered.', fix: 'Check whether they are needed at all, or should be recommendations or mandatory.' },
      spread_no_mandatory: { title: 'None of the {total} requirements is mandatory', detail: 'Without MUST/SHALL requirements nothing is binding.', fix: 'Mark the requirements that must be fulfilled as MUST (or SHALL).' },
      spread_many_should: { title: '{percent} % of the requirements are recommendations (SHOULD)', detail: 'SHOULD means "unless there is a good reason"; many of them make the delivery hard to judge.', fix: 'Decide which are really mandatory and which are optional.' },
      spread_many_descriptive: { title: '{percent} % of the requirements are descriptive', detail: 'Descriptive texts without obligation are information, not requirements.', fix: 'Move them to documentation, or give them an obligation level.' },
