      no_criteria: { title: 'Requirements without acceptance criteria: {n}', detail: 'Without criteria it is unclear when a requirement is fulfilled.', fix: 'Add measurable evaluation criteria.' },
      empty_description: { title: 'Requirements without a description: {n}', detail: 'The requirement consists of a title only.', fix: 'Write the requirement statement in the description.' },
