  obligationHelp: {
    summary: 'Help: obligation levels (MUST, SHOULD, MAY …)',
    intro: 'Every requirement states how binding it is with one keyword in capitals, as defined in RFC 2119 and RFC 8174. The keyword sets the obligation of the requirement; the language analysis below detects it.',
    keyword: 'Keyword',
    meaning: 'Meaning',
    example: 'Example',
    more: 'More in the user guide',
    tipCapitals: 'Write the keyword in capitals: only MUST, SHOULD, MAY … in capitals have the normative meaning; "must" in lower case is ordinary English.',
    tipOne: 'Use one keyword per requirement. A sentence with both MUST and MAY is two requirements.',
    tipConsistent: 'Be consistent: MUST, SHALL and REQUIRED mean the same, so pick one and use it in every requirement of the project (Analytics shows the spread).',
    tipMeasurable: 'Make it verifiable: avoid vague words such as fast or user-friendly, and give measurable acceptance criteria.',
    rows: {
      must: { keywords: 'MUST · SHALL · REQUIRED', meaning: 'An absolute requirement: it has to be fulfilled.', example: 'The system MUST log every sign-in.' },
      must_not: { keywords: 'MUST NOT · SHALL NOT', meaning: 'An absolute prohibition.', example: 'The system MUST NOT store passwords in plain text.' },
      should: { keywords: 'SHOULD · RECOMMENDED', meaning: 'Recommended: it may be left out for valid reasons, but the consequences must be understood and weighed.', example: 'The start page SHOULD load within 2 seconds.' },
      should_not: { keywords: 'SHOULD NOT · NOT RECOMMENDED', meaning: 'Discouraged: allowed only for valid, understood reasons.', example: 'Error messages SHOULD NOT show stack traces.' },
      may: { keywords: 'MAY · OPTIONAL', meaning: 'Truly optional: an implementation may or may not do it.', example: 'The user MAY export the report as PDF.' },
      will: { keywords: 'WILL', meaning: 'A statement of intent or fact, not a requirement on the system.', example: 'The customer WILL provide the test data.' },
      describe: { keywords: '(no keyword)', meaning: 'Descriptive information, not a requirement.', example: 'This section describes the payment flow.' },
    },
  },
